#include "opensim/services/simulation_connector.hpp"
#include "opensim/network/osd_json.hpp"
#include <iostream>
using namespace opensim;using network::Value;
std::string hex(std::string_view s){std::string out;const char* h="0123456789abcdef";for(unsigned char c:s){out+=h[c>>4];out+=h[c&15];}return out;}
std::string decode(const std::string& s){std::string out;for(std::size_t i=0;i<s.size();i+=2)out+=static_cast<char>(std::stoi(s.substr(i,2),nullptr,16));return out;}
framework::Uuid id(int n){return framework::Uuid("00000000-0000-0000-0000-00000000000"+std::to_string(n));}
services::GridRegion region(std::string uri="http://sim:9000/base/"){services::GridRegion d;d.id=id(9);d.x=25600;d.y=51200;d.name="Destination";d.set_server_uri(uri);return d;}
std::shared_ptr<framework::AgentData> data(){auto p=std::make_shared<framework::AgentData>();auto map=Value::object({});map.set("agent_uuid",id(7).str());map.set("position","<1.25, 2, 30>");p->unpack(map);return p;}
struct Harness:services::SimulationConnector{bool custom=false;using SimulationConnector::SimulationConnector;std::string agent_path()const override{return custom?"custom/":"agent/";}};
int main(int argc,char** argv){if(argc>1){services::SimulationConnector c;auto d=region(argv[1]);auto p=data();framework::EntityTransferContext context;bool first=c.update_agent(d,p,context);bool second=c.update_agent(d,p,context);auto value=Value::object({});value.set("first",Value(first));value.set("second",Value(second));value.set("failed",Value(static_cast<std::int32_t>(c.failed_simulator_count())));std::cout<<network::osd_json(value,true);return 0;}std::string line;while(std::getline(std::cin,line)){auto args=network::parse_osd_json(decode(line));int profile=network::osd_integer(args.get("profile")),calls=0;auto d=region();auto p=data();if(profile&8)p->god_data=std::make_shared<Value>();framework::EntityTransferContext context;context.outbound_version=static_cast<float>(network::osd_real(args.get("version")));std::string trace,result;Harness c({}, {},[&](const std::string& uri,const Value& body,int timeout,bool compressed){trace+=hex(uri)+":"+std::to_string(timeout)+":"+std::to_string(compressed)+":"+hex(network::osd_json(body,true))+";";auto& replies=args.get("replies").array;auto reply=replies.at(std::min<std::size_t>(calls++,replies.size()-1));if(reply.kind==Value::Kind::String&&reply.text=="throw")throw std::runtime_error("request");return reply;},{[]{return 0.;},false});c.custom=profile&16;for(int i=0;i<2;++i)try{result+=c.update_agent(profile&1?nullptr:&d,profile&2?nullptr:p,profile&4?nullptr:&context)?"1,":"0,";}catch(...){result+="EX,";}std::cout<<result<<"|"<<hex(trace)<<"|"<<c.failed_simulator_count()<<"|"<<(c.get_scene(id(9))==nullptr)<<"\n";}}
